<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CafeKiosk - Promotions & Discount</title><link rel="stylesheet" href="../Assets/css/admin-extension.css"><script src="../Assets/js/auth-session.js"></script>  <link rel="stylesheet" href="../Assets/css/uniform-theme.css?v=33">
  <link rel="stylesheet" href="../Assets/css/profile-menu.css?v=30">
  <link rel="stylesheet" href="/Assets/css/message-dialog.css?v=logout-confirm-v2">
  <link rel="icon" type="image/x-icon" href="/Assets/images/favicon.ico?v=20260923">
  <link rel="apple-touch-icon" href="/Assets/images/logo.png">
</head><body class="ck-admin-page uniform-admin"><div class="ck-shell"><aside class="ck-sidebar"><a class="ck-brand" href="/admin/dashboard"><img src="../Assets/images/logo.png" alt="CafeKiosk"></a><div class="ck-side-label">ADMIN</div><nav class="ck-nav">
<a href="/admin/dashboard"><span class="ico">▦</span><span class="label">Dashboard</span></a>
<a href="/admin/order-monitor"><span class="ico">🛒</span><span class="label">Order</span></a>
<a href="/admin/menu-management"><span class="ico">▤</span><span class="label">Menu Management</span></a>
<a href="/admin/promotions" class="active"><span class="ico">%</span><span class="label">Promotions & Discount</span></a>
<a href="/admin/inventory"><span class="ico">□</span><span class="label">Inventory</span></a>
<a href="/admin/report"><span class="ico">▥</span><span class="label">Report</span></a>
<a href="/admin/audit-logs"><span class="ico">▣</span><span class="label">Audit Logs</span></a>
<a href="/admin/users" class=""><span class="ico">●</span><span class="label">User</span></a>
<a href="/admin/settings" class=""><span class="ico">⚙</span><span class="label">Settings</span></a>
</nav></aside><main class="ck-main"><div class="ck-topbar"><div class="ck-title"><h1>Promotions & Discount</h1></div><div class="ck-profile"><span>● &nbsp;<span id="adminName">Administrator</span></span><span>⌄</span></div></div><section class="ck-card"><div class="ck-toolbar"><div><h2>Promotion Rules</h2><div class="ck-muted">Active rules automatically apply to eligible POS and Kiosk orders.</div></div><button class="ck-btn primary" id="newPromo">+ Create New Promotion</button></div><div id="promoTable"></div></section></main></div><div class="ck-modal" id="promoModal"><div class="ck-dialog"><div class="ck-toolbar"><h2 id="promoModalTitle">Create Promotion</h2><button class="ck-btn" id="closePromo">Close</button></div><form id="promoForm" class="ck-grid two"><input type="hidden" id="promoId"><div class="ck-field"><label>Promo Name</label><input class="ck-input" id="promoName" required></div><div class="ck-field"><label>Discount Type</label><select class="ck-select" id="promoType"><option value="percentage">Percentage Discount</option><option value="fixed">Fixed Amount Discount</option></select></div><div class="ck-field"><label>Discount Value</label><input class="ck-input" id="promoValue" type="number" min="0" step="0.01" required></div><div class="ck-field"><label>Minimum Subtotal</label><input class="ck-input" id="promoMinimum" type="number" min="0" step="0.01" value="0"></div><div class="ck-field"><label>Apply To</label><select class="ck-select" id="promoScope"><option value="all">All Items</option><option value="category">Specific Categories</option><option value="products">Specific Products</option></select></div><div class="ck-field"><label>Categories / Products</label><input class="ck-input" id="promoTargets" placeholder="Comma separated, e.g. Coffees, Milk Tea"></div><div class="ck-field"><label>Eligibility</label><select class="ck-select" id="promoEligibility" multiple size="4"><option value="all">All Customers</option><option value="student">Students</option><option value="senior">Senior Citizens</option><option value="pwd">PWD</option></select></div><div class="ck-field"><label>Status</label><select class="ck-select" id="promoActive"><option value="true">Active</option><option value="false">Inactive</option></select></div><div class="ck-field"><label>Start Date</label><input class="ck-input" id="promoStart" type="date"></div><div class="ck-field"><label>End Date</label><input class="ck-input" id="promoEnd" type="date"></div><div class="ck-field"><label>Start Time (optional)</label><input class="ck-input" id="promoStartTime" type="time"></div><div class="ck-field"><label>End Time (optional)</label><input class="ck-input" id="promoEndTime" type="time"></div><div class="ck-field" style="grid-column:1/-1"><label>Description / Condition</label><textarea class="ck-textarea" id="promoDescription" rows="3"></textarea></div><div class="ck-actions" style="grid-column:1/-1;justify-content:flex-end"><button class="ck-btn" type="button" id="cancelPromo">Cancel</button><button class="ck-btn primary" type="submit">Save Promotion</button></div></form></div></div><script src="../Assets/js/promotions-discount.js"></script>  <script src="../Assets/js/uniform-theme.js?v=33"></script>
  <script src="../Assets/js/profile-menu.js?v=logout-confirm-v2"></script>
  <script src="/Assets/js/message-dialog.js?v=logout-confirm-v2"></script>
</body></html>
